// ============================================================================
// src/lib/tools/ospf-cost-and-adjacency-checker/golden-vectors.ts
// ----------------------------------------------------------------------------
// GOLDEN VECTORS for the OSPF cost and adjacency checker.
//
// Every expected field of the COMPUTED table below was derived on 2026-11-08
// by a separate Python oracle (oracle.py, in the build's work folder), not by
// running this engine:
//   - costs with fractions.Fraction from each vendor's rule as its pages state
//     it (the Cisco auto-cost examples, the Junos reference-bandwidth pages,
//     the FRRouting auto-cost text, the two Extreme tables, the Arista and
//     AOS-CX defaults); the smallest distinguishing reference by brute force
//     over every whole Mbit/s (Cisco, FRRouting) or every multiple of the
//     speeds' greatest common divisor (Junos), not by the engine's breakpoint
//     search;
//   - adjacencies by a per-direction table of the receive checks of RFC 2328
//     s8.2, s10.5 and s10.6, RFC 5340 s4.2.2, RFC 3101 s2.1, RFC 5709 s3.4,
//     RFC 6549 s3.1, RFC 7166 s4.6 and RFC 4552 s3, with the adjacency
//     decision of s10.4 and the Leader/Follower cases of s10.6.
// A cross-check of every oracle field against the engine found no difference.
// The table was written from the oracle's output by a script (make_vectors.py),
// so no expected value was typed by hand. The sentences, the refusals and the
// API's text are written out at the end, each with the rule it pins. The
// page's two Examples and its chips (D-83, examples.ts) are pinned: every one
// of them is the request of a computed vector, which verifyVectors checks.
// GOLDEN_VECTOR_SET_ID changes whenever a vector changes (the api-sync rule).
//
// 2026-11-08b: the Huawei, Cisco, Arista and AOS-CX pages read in a browser on
// 2026-11-08 (the sites refuse automated reads) changed four vendor rules; the
// oracle was updated to restate them and the computed table regenerated
// (99 readings, 0 differences from the engine). Changed expectations: Cisco
// at or above the reference now costs 1, so its three chips, its auto-cost
// examples and its 1000 and 100000 references find smaller distinguishing
// references; Arista's chips cost 10 as "not-configured"; AOS-CX's chips are
// computed from its 100000 Mbps reference; Huawei's chips are computed; the
// written-out Arista, AOS-CX, Huawei and Cisco faster-than-reference sentences
// and the no-reference refusal (now Switch Engine) follow. Every other vector
// is unchanged.
// ============================================================================

import { run, runApi, type OspfRequest, type OspfResult } from "./compute"; // the engine's API entries
import { EXAMPLE_COST_REQUEST, EXAMPLE_ADJACENCY_REQUEST, ADJACENCY_SCENARIOS, COST_SPEED_CHIPS } from "./examples"; // the page's Examples and chips, pinned below

/** The set id: dated, changed with any vector (scripts/check-api-sync.mjs compares it with scripts/api-sync.json). */
export const GOLDEN_VECTOR_SET_ID = "ospf-cost-and-adjacency-checker-golden-2026-11-08b"; // 2026-11-08b: Huawei, Cisco, Arista and AOS-CX rules from the browser reads; 2026-11-08: the first set

/** One vector: a request (or raw API text), and either the fields expected or the error expected. */
export interface OspfVector {
  /** A stable id. */
  id: string;
  /** Where the expected values come from. */
  note: string;
  /** The request object (run()). */
  request?: OspfRequest;
  /** Or the raw API body (runApi()). */
  api?: string;
  /** The fields expected (objects compared as subsets, arrays element by element). */
  expect?: Record<string, unknown>;
  /** Text the reading's sentences must contain. */
  contains?: { notes?: string[]; warnings?: string[]; verdictText?: string; findings?: string[]; vendor?: string[] };
  /** Text no note or warning may contain (2026-11-08b: a sentence that must not appear). */
  lacks?: { notes?: string[]; warnings?: string[] };
  /** The error expected, as a pattern over its message. */
  expectError?: RegExp;
}

/** The page's Examples and chips, re-exported by the conventional names. */
export { EXAMPLE_COST_REQUEST, EXAMPLE_ADJACENCY_REQUEST, ADJACENCY_SCENARIOS, COST_SPEED_CHIPS }; // from examples.ts

