/** Every vector, in order. */
export const OSPF_VECTORS: readonly OspfVector[] = Object.freeze([...COMPUTED_VECTORS, ...OTHER_VECTORS]); // the table first, then the rest

/**
 * Whether `actual` holds `expected`: objects as subsets, arrays of the same length element by element, anything else
 * exactly as JSON.
 * @param actual the reading's value
 * @param expected the vector's value
 * @returns true when it matches
 */
function matches(actual: unknown, expected: unknown): boolean {
  if (Array.isArray(expected)) { // a list
    if (!Array.isArray(actual) || actual.length !== expected.length) return false; // the same length
    return expected.every((e, i) => matches(actual[i], e)); // each element
  } // array
  if (expected !== null && typeof expected === "object") { // a subset object
    if (actual === null || typeof actual !== "object") return false; // nothing to compare with
    return Object.entries(expected as Record<string, unknown>).every(([k, v]) => matches((actual as Record<string, unknown>)[k], v)); // each field
  } // object
  return JSON.stringify(actual) === JSON.stringify(expected); // exact, as JSON
} // matches

/** The report verifyVectors returns. */
export interface VerifyReport {
  /** The set id. */
  setId: string;
  /** Vectors run. */
  total: number;
  /** Vectors that passed. */
  passed: number;
  /** One line per failure (empty when all pass). */
  failures: string[];
}

/**
 * Run every vector, then check that each Example and chip of the page is the request of a computed vector.
 * @returns the report (failures empty when all pass)
 */
export function verifyVectors(): VerifyReport {
  const failures: string[] = []; // collected
  for (const v of OSPF_VECTORS) { // each vector
    let r: OspfResult | null = null; // the reading
    try { // attempt
      r = v.api !== undefined ? runApi(v.api) : run(v.request as OspfRequest); // the API text or the request
    } catch (e) { // refused
      const msg = e instanceof Error ? e.message : String(e); // the refusal
      if (!v.expectError) failures.push(`${v.id}: unexpected error: ${msg}`); // should have computed
      else if (!v.expectError.test(msg)) failures.push(`${v.id}: error mismatch: ${msg}`); // the wrong refusal
      continue; // next vector
    } // ran
    if (v.expectError) { failures.push(`${v.id}: expected an error, got a reading`); continue; } // should have refused
    if (v.expect && !matches(r, v.expect)) failures.push(`${v.id}: fields differ: ${JSON.stringify(r).slice(0, 400)}`); // a value moved
    const c = v.contains ?? {}; // the texts expected
    const rec = r as unknown as { notes?: string[]; warnings?: string[]; verdictText?: string; findings?: { text: string; vendor: string[] }[] }; // the sentence fields
    for (const s of c.notes ?? []) if (!(rec.notes ?? []).some((n) => n.includes(s))) failures.push(`${v.id}: no note contains "${s}"`); // notes
    for (const s of c.warnings ?? []) if (!(rec.warnings ?? []).some((w) => w.includes(s))) failures.push(`${v.id}: no warning contains "${s}"`); // warnings
    if (c.verdictText && !String(rec.verdictText ?? "").includes(c.verdictText)) failures.push(`${v.id}: verdict text lacks "${c.verdictText}"`); // the verdict
    for (const s of c.findings ?? []) if (!(rec.findings ?? []).some((f) => f.text.includes(s))) failures.push(`${v.id}: no finding contains "${s}"`); // findings
    for (const s of c.vendor ?? []) if (!(rec.findings ?? []).some((f) => f.vendor.some((x) => x.includes(s)))) failures.push(`${v.id}: no vendor note contains "${s}"`); // vendor notes
    const l = v.lacks ?? {}; // the texts that must not appear (2026-11-08b)
    for (const s of l.notes ?? []) if ((rec.notes ?? []).some((n) => n.includes(s))) failures.push(`${v.id}: a note contains "${s}"`); // notes
    for (const s of l.warnings ?? []) if ((rec.warnings ?? []).some((w) => w.includes(s))) failures.push(`${v.id}: a warning contains "${s}"`); // warnings
  } // vectors
  const pinned = new Set(COMPUTED_VECTORS.map((v) => JSON.stringify(v.request))); // every computed request
  const pages: [string, unknown][] = [["EXAMPLE_COST_REQUEST", EXAMPLE_COST_REQUEST], ["EXAMPLE_ADJACENCY_REQUEST", EXAMPLE_ADJACENCY_REQUEST], ...Object.entries(ADJACENCY_SCENARIOS).map(([k, r]) => [`ADJACENCY_SCENARIOS.${k}`, r] as [string, unknown]), ...COST_SPEED_CHIPS.map((c) => [`COST_SPEED_CHIPS ${c}`, { mode: "cost", vendor: "juniper-junos", reference: "", links: c }] as [string, unknown])]; // what the page's buttons fill
  for (const [name, req] of pages) if (!pinned.has(JSON.stringify(req))) failures.push(`${name}: not the request of a computed vector`); // pinned
  return { setId: GOLDEN_VECTOR_SET_ID, total: OSPF_VECTORS.length, passed: OSPF_VECTORS.length - new Set(failures.map((f) => f.split(":")[0])).size, failures }; // the report
} // verifyVectors
